# -*- coding: utf-8 -*-
# PPPE / biosecurity terms.
GLOSSARY_ADD = [
    {"term": "PPE / PPPE", "defn": "PPE is personal protective equipment, and PPPE is plant and personal protective equipment. In a grow room, the same gown, gloves and protective covers give the crop protection against the person, and give the person protection against risks.", "tags": ["operations", "health"]},
    {"term": "Gowning / de-gowning", "defn": "Gowning is the procedure to put on protective clothing, and de-gowning is the procedure to remove it. You do the two procedures in a specified sequence at the clean/dirty line, and thus contamination does not go across it. You put on the gown from the top to the bottom, and you remove it in the opposite sequence, with the dirtiest item first.", "tags": ["operations", "health"]},
    {"term": "Fomite", "defn": "A fomite is an object that holds microbes and moves them to a different object. Examples are a phone, a pen, a tool or a handle. Hands move contamination from fomites to the crop.", "tags": ["health"]},
    {"term": "Bioaerosol", "defn": "Bioaerosol is a group of particles in the air that contain organisms. Examples are small pieces of skin with bacteria, fungal spores, and drops of liquid from a person who speaks or from a toilet flush.", "tags": ["health"]},
    {"term": "Cross-contamination", "defn": "Cross-contamination is the movement of contamination from a dirty area or item to a clean area or item. For example, a person goes from the flower area back to the propagation area and does not put on a gown again.", "tags": ["operations", "health"]},
    {"term": "Hierarchy of controls", "defn": "The hierarchy of controls is the sequence of steps that the regulations give for the control of risk. The steps are: remove the risk, replace it, isolate it, use engineering controls, use administrative controls, and last, use PPE.", "tags": ["operations"]},
    {"term": "PCBU", "defn": "PCBU is the person conducting a business or undertaking. It is the term that the Health and Safety at Work Act 2015 of NZ uses for the employer, who has the legal duty.", "tags": ["operations"]},
]
